<?php
include 'includes/cek_session.php'; include 'config/koneksi.php';
$embed=(($_GET['embed']??'')==='1'); function eCat($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$qSiswa=mysqli_query($koneksi,"SELECT s.id,s.nis,s.nama,COALESCE(k.nama,'Belum ditempatkan') nama_kelas FROM t_siswa s LEFT JOIN t_kelas_siswa ks ON ks.siswa_id=s.id AND ks.status_aktif=1 LEFT JOIN t_kelas k ON k.id=ks.kelas_id WHERE s.status_aktif=1 ORDER BY s.nama");
$qPelanggaran=mysqli_query($koneksi,"SELECT id,kode,nama,poin FROM t_pelanggaran WHERE status_aktif=1 ORDER BY nama");
$qRiwayat=mysqli_query($koneksi,"SELECT id,tanggal,nama_siswa,nama_kelas,nama_pelanggaran,poin,keterangan,nama_guru FROM t_pelanggaran_siswa ORDER BY tanggal DESC,id DESC LIMIT 100");
if(!$qSiswa||!$qPelanggaran||!$qRiwayat)die('Gagal memuat data: '.eCat(mysqli_error($koneksi)));
$namaGuru=trim($_SESSION['name']??'Guru');
$st=mysqli_prepare($koneksi,"SELECT nama FROM t_guru WHERE user_id=? AND status_aktif=1 LIMIT 1");$uid=(int)($_SESSION['id']??0);mysqli_stmt_bind_param($st,'i',$uid);mysqli_stmt_execute($st);$g=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if($g&&!empty($g['nama']))$namaGuru=$g['nama'];
?>
<?php if(!$embed):?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catat Pelanggaran</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php endif;?>
<main class="container-fluid p-3 p-md-4 bg-white"><div class="mb-3"><h2 class="fw-bold">Catat Pelanggaran Siswa</h2><p class="text-secondary">Tambahkan catatan pelanggaran siswa dan kronologi kejadian.</p></div>
<?php if(!empty($_SESSION['pesan'])):?><div class="alert alert-info alert-dismissible fade show"><?=eCat($_SESSION['pesan'])?><button type="button" class="btn-close" data-bs-dismiss="alert"></button></div><?php unset($_SESSION['pesan']);endif;?>
<div class="card border-0 shadow-sm mb-4"><div class="card-header bg-primary text-white fw-semibold">Form Tambah Pelanggaran</div><div class="card-body"><form method="post" action="simpan_catatan_pelanggaran.php"><input type="hidden" name="embed" value="<?=$embed?'1':'0'?>"><div class="row g-3">
<div class="col-md-6"><label class="form-label">Nama Siswa</label><select name="siswa_id" class="form-select" required><option value="">-- Pilih Siswa --</option><?php while($s=mysqli_fetch_assoc($qSiswa)):?><option value="<?=(int)$s['id']?>"><?=eCat($s['nis'])?> - <?=eCat($s['nama'])?> (<?=eCat($s['nama_kelas'])?>)</option><?php endwhile;?></select></div>
<div class="col-md-6"><label class="form-label">Jenis Pelanggaran</label><select name="pelanggaran_id" id="jenisPelanggaran" class="form-select" required><option value="">-- Pilih Pelanggaran --</option><?php while($p=mysqli_fetch_assoc($qPelanggaran)):?><option value="<?=(int)$p['id']?>" data-poin="<?=(int)$p['poin']?>"><?=eCat($p['kode'])?> - <?=eCat($p['nama'])?> (<?=(int)$p['poin']?> poin)</option><?php endwhile;?></select></div>
<div class="col-md-4"><label class="form-label">Tanggal Kejadian</label><input type="date" name="tanggal" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-md-4"><label class="form-label">Poin</label><input id="poinPelanggaran" class="form-control" value="0" readonly></div><div class="col-md-4"><label class="form-label">Guru Pencatat</label><input class="form-control" value="<?=eCat($namaGuru)?>" readonly></div>
<div class="col-12"><label class="form-label">Keterangan / Kronologi</label><textarea name="keterangan" class="form-control" rows="3" required placeholder="Jelaskan kejadian secara singkat dan jelas..."></textarea></div><div class="col-12"><label class="form-label">Tindakan Awal (opsional)</label><textarea name="tindakan" class="form-control" rows="2" placeholder="Contoh: Teguran lisan atau pembinaan"></textarea><div class="form-text">Tindakan bisa diperbarui melalui menu Tindakan.</div></div></div><button class="btn btn-primary mt-3" type="submit">Simpan Pelanggaran</button> <button class="btn btn-outline-secondary mt-3" type="reset">Reset</button></form></div></div>
<div class="card border-0 shadow-sm"><div class="card-header bg-light fw-semibold">Catatan Pelanggaran Terbaru</div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover align-middle"><thead class="table-light"><tr><th>No</th><th>Tanggal</th><th>Siswa</th><th>Kelas</th><th>Pelanggaran</th><th>Poin</th><th>Keterangan</th><th>Guru</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($qRiwayat)):?><tr><td><?=$no++?></td><td><?=eCat($r['tanggal'])?></td><td><?=eCat($r['nama_siswa'])?></td><td><?=eCat($r['nama_kelas'])?></td><td><?=eCat($r['nama_pelanggaran'])?></td><td><span class="badge text-bg-danger"><?=(int)$r['poin']?></span></td><td><?=eCat($r['keterangan'])?></td><td><?=eCat($r['nama_guru'])?></td></tr><?php endwhile;?><?php if(mysqli_num_rows($qRiwayat)===0):?><tr><td colspan="8" class="text-center text-muted">Belum ada catatan pelanggaran.</td></tr><?php endif;?></tbody></table></div></div></div></main>
<script>const jp=document.getElementById('jenisPelanggaran'),pp=document.getElementById('poinPelanggaran');jp?.addEventListener('change',()=>pp.value=jp.selectedOptions[0]?.dataset.poin||0);</script><?php if(!$embed):?></body></html><?php endif;?>
